import{_ as o,o as a,c as t,a2 as s}from"./chunks/framework.Wk4ah3nE.js";const u=JSON.parse('{"title":"Known limitations","description":"A complete, honest catalogue of the known defects and design constraints in Proxmox VM Autoscale, with the impact of each and the workaround where one exists.","frontmatter":{"title":"Known limitations","description":"A complete, honest catalogue of the known defects and design constraints in Proxmox VM Autoscale, with the impact of each and the workaround where one exists.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/reference/limitations.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/reference/limitations.html"}],["meta",{"property":"og:title","content":"Known limitations"}],["meta",{"property":"og:description","content":"A complete, honest catalogue of the known defects and design constraints in Proxmox VM Autoscale, with the impact of each and the workaround where one exists."}]]},"headers":[],"relativePath":"reference/limitations.md","filePath":"reference/limitations.md","lastUpdated":null}'),n={name:"reference/limitations.md"};function i(r,e,d,c,l,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h1><p>Everything on this page is known and reproducible at the time of writing. It is here so you can decide what you are accepting before you run this against your infrastructure, rather than discovering it from a log line at 3am.</p><p>Items are grouped by whether they can bite you silently.</p><h2 id="silent-failure-modes" tabindex="-1">Silent failure modes <a class="header-anchor" href="#silent-failure-modes" aria-label="Permalink to &quot;Silent failure modes&quot;">​</a></h2><p>These produce wrong behaviour without an obvious error.</p><h3 id="metric-parsing-is-format-sensitive" tabindex="-1">Metric parsing is format-sensitive <a class="header-anchor" href="#metric-parsing-is-format-sensitive" aria-label="Permalink to &quot;Metric parsing is format-sensitive&quot;">​</a></h3><p>Guest usage comes from scraping a human-readable table:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pvesh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /cluster/resources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;qemu/&lt;vmid&gt;&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;│&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $6, $15, $16}&#39;</span></span></code></pre></div><p>This depends on the box-drawing separator, on those exact column indices, and on <code>grep</code> matching only the intended row. Any of them can change between Proxmox versions.</p><p><strong>Impact:</strong> when parsing fails, usage falls back to <code>0.0</code>. Zero is below every reasonable <code>low</code> threshold, so <strong>a parse failure is indistinguishable from an idle guest</strong> and walks every affected VM down to its minimum, one step per cycle.</p><p><strong>Detection:</strong> <code>CPU usage not found in output.</code> / <code>RAM memory values not found in output.</code> in the log.</p><p><strong>Workaround:</strong> verify the command by hand on your Proxmox version before deploying, and alert on those warnings. A <code>--output-format json</code> implementation would remove the whole class of problem.</p><h3 id="grep-qemu-101-also-matches-vmid-1010" tabindex="-1"><code>grep &#39;qemu/101&#39;</code> also matches VMID 1010 <a class="header-anchor" href="#grep-qemu-101-also-matches-vmid-1010" aria-label="Permalink to &quot;`grep &#39;qemu/101&#39;` also matches VMID 1010&quot;">​</a></h3><p>The VMID filter is a substring match, so a four-digit VMID beginning with your three-digit one matches too, and <code>awk</code> reads whichever row came first.</p><p><strong>Impact:</strong> decisions made from another VM&#39;s usage.</p><p><strong>Workaround:</strong> avoid VMID prefixes of each other among managed VMs.</p><h3 id="a-proxmox-host-typo-skips-the-vm-without-a-word" tabindex="-1">A <code>proxmox_host</code> typo skips the VM without a word <a class="header-anchor" href="#a-proxmox-host-typo-skips-the-vm-without-a-word" aria-label="Permalink to &quot;A `proxmox_host` typo skips the VM without a word&quot;">​</a></h3><p>VMs are matched to hosts by exact string equality on <code>name</code>. A mismatch means the VM entry is never reached — no warning, no error, it simply never appears in the log.</p><p><strong>Workaround:</strong> after any config change, confirm every managed VM appears in a <code>VM &lt;id&gt; current usage</code> line within one cycle.</p><h3 id="command-failures-are-reported-as-successes" tabindex="-1">Command failures are reported as successes <a class="header-anchor" href="#command-failures-are-reported-as-successes" aria-label="Permalink to &quot;Command failures are reported as successes&quot;">​</a></h3><p><code>execute_command</code> returns output and exit status without raising on a non-zero status, and the callers that issue <code>qm set</code> discard the result. So:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[INFO] RAM balloon set to 4096 MB for VM 101 (hotplug applied).</span></span></code></pre></div><p>is logged whether or not <code>qm set</code> succeeded, and whether or not the guest honoured it.</p><p><strong>Workaround:</strong> verify with <code>qm config &lt;vmid&gt;</code> when a change matters.</p><h3 id="per-vm-thresholds-are-ignored" tabindex="-1">Per-VM <code>thresholds</code> are ignored <a class="header-anchor" href="#per-vm-thresholds-are-ignored" aria-label="Permalink to &quot;Per-VM `thresholds` are ignored&quot;">​</a></h3><p><code>config.yaml</code> shows a <code>thresholds:</code> block inside each <code>virtual_machines</code> entry. Nothing reads it — only the global <code>scaling_thresholds</code> is consulted.</p><p><strong>Impact:</strong> you may believe a VM has bespoke thresholds when it does not.</p><p><strong>Workaround:</strong> run a second instance with its own config for a VM that genuinely needs different numbers.</p><h3 id="downtime-is-billed-as-uptime" tabindex="-1">Downtime is billed as uptime <a class="header-anchor" href="#downtime-is-billed-as-uptime" aria-label="Permalink to &quot;Downtime is billed as uptime&quot;">​</a></h3><p><code>BillingTracker._calculate_resource_cost</code> accepts the uptime records and never uses them, despite an in-code comment saying cost is charged for uptime only. Compounding this, nothing in the service calls <code>record_vm_state_change</code>, so there are no uptime records to begin with — every report shows 100% uptime.</p><p><strong>Impact:</strong> a VM powered off for a week is billed for that week at its last known spec.</p><p><strong>Workaround:</strong> reconcile against your own uptime source before invoicing.</p><h2 id="documented-but-absent-behaviour" tabindex="-1">Documented-but-absent behaviour <a class="header-anchor" href="#documented-but-absent-behaviour" aria-label="Permalink to &quot;Documented-but-absent behaviour&quot;">​</a></h2><h3 id="billing-reports-are-not-generated-automatically" tabindex="-1">Billing reports are not generated automatically <a class="header-anchor" href="#billing-reports-are-not-generated-automatically" aria-label="Permalink to &quot;Billing reports are not generated automatically&quot;">​</a></h3><p>Enabling <code>billing</code> wires up exactly one thing: recording a spec change after each successful scaling action. <code>generate_period_report</code>, <code>export_csv</code>, <code>run_webhook</code>, <code>record_vm_state_change</code> and <code>set_vm_name</code> are public API that nothing calls.</p><p><strong>Impact:</strong> no CSV appears, no webhook fires, no uptime is tracked.</p><p><strong>Workaround:</strong> the <a href="/proxmox-vm-autoscale/guide/billing.html#generating-a-report">billing page</a> has a script that calls the API on a schedule.</p><h3 id="logging-in-config-yaml-is-inert-by-default" tabindex="-1"><code>logging</code> in <code>config.yaml</code> is inert by default <a class="header-anchor" href="#logging-in-config-yaml-is-inert-by-default" aria-label="Permalink to &quot;`logging` in `config.yaml` is inert by default&quot;">​</a></h3><p>If <code>logging_config.json</code> exists it is loaded via <code>dictConfig</code> and the <code>logging</code> section of <code>config.yaml</code> is never consulted. The installer ships that file, so in a default install the YAML block does nothing.</p><p><strong>Workaround:</strong> edit <code>logging_config.json</code>.</p><h2 id="operational-constraints" tabindex="-1">Operational constraints <a class="header-anchor" href="#operational-constraints" aria-label="Permalink to &quot;Operational constraints&quot;">​</a></h2><h3 id="cooldown-state-is-lost-on-restart" tabindex="-1">Cooldown state is lost on restart <a class="header-anchor" href="#cooldown-state-is-lost-on-restart" aria-label="Permalink to &quot;Cooldown state is lost on restart&quot;">​</a></h3><p>Cooldown timers live in process memory. <code>systemctl restart</code> clears them and the first cycle after can scale immediately. Repeated restarts remove rate limiting entirely.</p><h3 id="check-interval-is-a-floor-not-a-period" tabindex="-1"><code>check_interval</code> is a floor, not a period <a class="header-anchor" href="#check-interval-is-a-floor-not-a-period" aria-label="Permalink to &quot;`check_interval` is a floor, not a period&quot;">​</a></h3><p>Cycles are sequential and blocking: one SSH connection per VM, opened and closed, hosts processed one after another. With many VMs a cycle can exceed <code>check_interval</code>, at which point cycles simply run back to back. There is no parallelism and no scheduling guarantee.</p><h3 id="the-host-gate-blocks-scale-down-too" tabindex="-1">The host gate blocks scale-down too <a class="header-anchor" href="#the-host-gate-blocks-scale-down-too" aria-label="Permalink to &quot;The host gate blocks scale-down too&quot;">​</a></h3><p>A node above <code>max_host_cpu_percent</code> or <code>max_host_ram_percent</code> has <em>all</em> scaling suppressed on it, including shrinking idle guests — the one action that would give the node headroom back.</p><h3 id="step-sizes-are-not-configurable" tabindex="-1">Step sizes are not configurable <a class="header-anchor" href="#step-sizes-are-not-configurable" aria-label="Permalink to &quot;Step sizes are not configurable&quot;">​</a></h3><p>Fixed at 1 core and 512 MB per action, in <code>vm_manager.py</code>. Recovering from a large jump takes many cycles.</p><h3 id="limits-are-global" tabindex="-1">Limits are global <a class="header-anchor" href="#limits-are-global" aria-label="Permalink to &quot;Limits are global&quot;">​</a></h3><p><code>scaling_limits</code> applies to every VM. A 2-core web server and a 16-core database cannot have different ceilings in one instance.</p><h3 id="single-instance-no-ha" tabindex="-1">Single instance, no HA <a class="header-anchor" href="#single-instance-no-ha" aria-label="Permalink to &quot;Single instance, no HA&quot;">​</a></h3><p>One process, no leader election, no shared state. Two instances managing the same VM will fight, since neither sees the other&#39;s cooldowns.</p><h3 id="ssh-port-is-read-unconditionally" tabindex="-1"><code>ssh_port</code> is read unconditionally <a class="header-anchor" href="#ssh-port-is-read-unconditionally" aria-label="Permalink to &quot;`ssh_port` is read unconditionally&quot;">​</a></h3><p><code>host[&#39;ssh_port&#39;]</code> is indexed directly rather than via <code>.get()</code>, so a host entry without that key raises <code>KeyError</code> and every VM on it fails. The shipped example config omits it on <code>host2</code>.</p><p><strong>Workaround:</strong> set <code>ssh_port</code> on every host.</p><h3 id="ssh-password-silently-overrides-ssh-key" tabindex="-1"><code>ssh_password</code> silently overrides <code>ssh_key</code> <a class="header-anchor" href="#ssh-password-silently-overrides-ssh-key" aria-label="Permalink to &quot;`ssh_password` silently overrides `ssh_key`&quot;">​</a></h3><p>When both are present the password is used. The shipped example fills in both with placeholders.</p><h2 id="security-constraints" tabindex="-1">Security constraints <a class="header-anchor" href="#security-constraints" aria-label="Permalink to &quot;Security constraints&quot;">​</a></h2><p>Covered in full in the <a href="/proxmox-vm-autoscale/security/">threat model</a>; summarised here.</p><h3 id="only-rsa-ssh-keys-are-supported" tabindex="-1">Only RSA SSH keys are supported <a class="header-anchor" href="#only-rsa-ssh-keys-are-supported" aria-label="Permalink to &quot;Only RSA SSH keys are supported&quot;">​</a></h3><p>The key file is loaded specifically as an RSA key, so Ed25519 and ECDSA keys fail to load — despite <code>SECURITY.md</code> recommending Ed25519.</p><p><strong>Workaround:</strong> <code>ssh-keygen -t rsa -b 4096</code>, or use password authentication.</p><h3 id="ssh-host-keys-are-accepted-automatically" tabindex="-1">SSH host keys are accepted automatically <a class="header-anchor" href="#ssh-host-keys-are-accepted-automatically" aria-label="Permalink to &quot;SSH host keys are accepted automatically&quot;">​</a></h3><p>The client uses an auto-add policy: any host key is trusted on first contact and no pinning is performed. An attacker positioned between the service and a node can present their own key and receive your root credentials.</p><p><strong>Workaround:</strong> the <a href="/proxmox-vm-autoscale/security/hardening.html#pin-ssh-host-keys">hardening guide</a> shows how to constrain this at the network and configuration level.</p><h3 id="credentials-are-stored-in-plain-text" tabindex="-1">Credentials are stored in plain text <a class="header-anchor" href="#credentials-are-stored-in-plain-text" aria-label="Permalink to &quot;Credentials are stored in plain text&quot;">​</a></h3><p><code>ssh_password</code>, <code>smtp_password</code> and <code>app_token</code> are read from <code>config.yaml</code> as-is. There is no secrets backend and no environment-variable support.</p><p><strong>Workaround:</strong> mode <code>600</code>, root-owned, on an encrypted filesystem; prefer key authentication over passwords.</p><h3 id="the-service-runs-as-root-unconfined" tabindex="-1">The service runs as root, unconfined <a class="header-anchor" href="#the-service-runs-as-root-unconfined" aria-label="Permalink to &quot;The service runs as root, unconfined&quot;">​</a></h3><p>The shipped unit sets <code>User=root</code> with no systemd sandboxing directives.</p><p><strong>Workaround:</strong> <a href="/proxmox-vm-autoscale/security/hardening.html#confine-the-systemd-unit">hardening drop-in</a>.</p><h3 id="vmids-are-interpolated-into-shell-commands" tabindex="-1">VMIDs are interpolated into shell commands <a class="header-anchor" href="#vmids-are-interpolated-into-shell-commands" aria-label="Permalink to &quot;VMIDs are interpolated into shell commands&quot;">​</a></h3><p><code>vm_id</code> from the config is formatted straight into command strings without validation. Since the config is administrator-controlled this is not remotely exploitable, but a malformed VMID produces malformed commands rather than a clear error.</p><h2 id="project-level-notes" tabindex="-1">Project-level notes <a class="header-anchor" href="#project-level-notes" aria-label="Permalink to &quot;Project-level notes&quot;">​</a></h2><h3 id="release-tags-are-not-in-chronological-order" tabindex="-1">Release tags are not in chronological order <a class="header-anchor" href="#release-tags-are-not-in-chronological-order" aria-label="Permalink to &quot;Release tags are not in chronological order&quot;">​</a></h3><p><code>v1.2.0</code> was published in December 2025, <code>v0.1.1</code> in April 2026 — and <code>v0.1.1</code> is the current release. The numbering does not reflect ordering, and the changelog does not mention <code>v1.2.0</code>.</p><h3 id="no-dry-run-mode" tabindex="-1">No dry-run mode <a class="header-anchor" href="#no-dry-run-mode" aria-label="Permalink to &quot;No dry-run mode&quot;">​</a></h3><p>There is no way to see what the service <em>would</em> do. The closest approximation is <code>scaling_enabled: false</code> everywhere, which produces the monitoring output without acting.</p><h3 id="no-metrics-endpoint" tabindex="-1">No metrics endpoint <a class="header-anchor" href="#no-metrics-endpoint" aria-label="Permalink to &quot;No metrics endpoint&quot;">​</a></h3><p>No Prometheus exporter, no health endpoint, no structured events. Monitoring means parsing the log — see <a href="/proxmox-vm-autoscale/guide/operations.html#monitoring-the-autoscaler-itself">operations</a>.</p><hr><p>Found something not on this list? <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/new/choose" target="_blank" rel="noreferrer">Open an issue</a>. For anything with security impact, follow <a href="/proxmox-vm-autoscale/security/disclosure.html">responsible disclosure</a> instead.</p>',83)])])}const m=o(n,[["render",i]]);export{u as __pageData,m as default};
